package com.MechGaming.settlements.config;
import net.minecraftforge.common.config.Configuration;
import net.minecraft.nbt.NBTTagCompound;
import java.io.File;

public final class SettlementConfig {
    private static Configuration config;
    public static int radius=32,requiredFlags=1,requiredPlayers=1,proposalMinutes=10,maxSettlements=512,maxZones=512,maxZoneSize=4096,spawnMinDistance=16,spawnMaxDistance=64,firstSettlementDistance=0,decaySeconds=300;
    public static boolean defaultAllowed=true,protectClaims=true,preventBuildOutsideZones=false,decayOutsideZones=false,advancedZoneSettings=false,mobsAttackSettlement=false,requireMobZone=false,raidsWithoutRuin=false,warsWithoutRuin=false;
    public static String[] blacklist=new String[0];
    public static boolean mobDestruction=false,mobPlacement=false,autoRepair=true,enableNpcs=true,warGhostProtection=true;
    public static int maxNpcs=8,maxBlueprintVolume=32768,raidWaves=3,raidMobsPerWave=4,raidRewardEmeralds=4;
    private SettlementConfig(){}
    public static void load(File file){config=new Configuration(file);config.load();read();save();}
    private static void read(){
        radius=config.getInt("radius","settlements",32,4,128,"Claim half width in blocks; new settlements only.");
        requiredFlags=config.getInt("requiredFlags","settlements",1,1,64,"Flag items consumed when a proposal becomes a settlement.");
        requiredPlayers=config.getInt("requiredPlayers","settlements",1,1,64,"Willing online players standing inside a proposal to establish it.");
        proposalMinutes=config.getInt("proposalMinutes","settlements",10,1,120,"Proposal lifetime in real minutes.");
        maxSettlements=config.getInt("maxSettlements","limits",512,1,2048,"Maximum settlements per world.");maxZones=config.getInt("maxZones","limits",512,1,2048,"Maximum administrator zones per world.");maxZoneSize=config.getInt("maxZoneSize","limits",4096,1,30000000,"Maximum zone side length.");
        defaultAllowed=config.getBoolean("defaultAllowed","zones",true,"Allow new settlements outside explicit build zones.");protectClaims=config.getBoolean("protectClaims","settlements",true,"Protect claims against nonmembers, explosions, fire, and hostile block changes.");
        preventBuildOutsideZones=config.getBoolean("preventBuildOutsideZones","zones",false,"Prevent building in areas restricted for settlements.");decayOutsideZones=config.getBoolean("decayOutsideZones","zones",false,"Newly placed blocks in restricted areas decay after the configured delay. Existing terrain is never scanned.");advancedZoneSettings=config.getBoolean("advancedZoneSettings","zones",false,"Allow per-zone build prevention, decay and block blacklist overrides.");
        decaySeconds=config.getInt("decaySeconds","zones",300,10,86400,"Delay before newly placed restricted blocks decay.");firstSettlementDistance=config.getInt("firstSettlementDistance","zones",0,0,1000000,"If positive, additional flags must be within this distance of the world's first settlement.");blacklist=config.getStringList("blacklist","zones",new String[0],"Block registry names prohibited in restricted build areas.");
        mobsAttackSettlement=config.getBoolean("mobsAttackSettlement","defense",false,"Enable optional settlement raids.");requireMobZone=config.getBoolean("requireMobZone","defense",false,"Require an allowed spawn zone intersecting each new settlement's outer spawning ring.");spawnMinDistance=config.getInt("spawnMinDistance","defense",16,0,256,"Minimum horizontal distance outside a claim for hostile spawning.");spawnMaxDistance=config.getInt("spawnMaxDistance","defense",64,1,512,"Maximum horizontal distance outside a claim for raid spawning.");
        raidsWithoutRuin=config.getBoolean("raidsWithoutRuin","defense",false,"Restore an explicit blueprint after a raid ends.");warsWithoutRuin=config.getBoolean("warsWithoutRuin","war",false,"Allow mutually agreed settlement wars.");
        mobDestruction=config.getBoolean("mobDestruction","defense",false,"Allow raid mobs to break ordinary non-tile blocks on their path.");mobPlacement=config.getBoolean("mobPlacement","defense",false,"Allow raid mobs to place temporary climbing blocks.");autoRepair=config.getBoolean("autoRepair","blueprints",true,"Allow owners to repair missing blueprint blocks using inventory materials.");enableNpcs=config.getBoolean("enableNpcs","npc",true,"Enable configurable settlement room and resident checks.");maxNpcs=config.getInt("maxNpcs","npc",8,0,64,"Maximum residents per settlement.");maxBlueprintVolume=config.getInt("maxBlueprintVolume","blueprints",32768,1,262144,"Maximum block volume captured by an explicit blueprint.");raidWaves=config.getInt("raidWaves","defense",3,1,20,"Waves per raid.");raidMobsPerWave=config.getInt("raidMobsPerWave","defense",4,1,64,"Mobs per raid wave.");raidRewardEmeralds=config.getInt("raidRewardEmeralds","defense",4,0,64,"Emerald reward for surviving a raid.");
        warGhostProtection=config.getBoolean("warGhostProtection","war",true,"Protect opted-out settlement members from all damage only while inside an active war claim.");spawnMaxDistance=Math.max(spawnMinDistance+1,spawnMaxDistance);
    }
    public static NBTTagCompound snapshot(){NBTTagCompound n=new NBTTagCompound();n.setInteger("radius",radius);n.setInteger("requiredFlags",requiredFlags);n.setInteger("requiredPlayers",requiredPlayers);n.setInteger("spawnMinDistance",spawnMinDistance);n.setInteger("spawnMaxDistance",spawnMaxDistance);n.setInteger("firstSettlementDistance",firstSettlementDistance);n.setInteger("decaySeconds",decaySeconds);n.setBoolean("defaultAllowed",defaultAllowed);n.setBoolean("protectClaims",protectClaims);n.setBoolean("preventBuildOutsideZones",preventBuildOutsideZones);n.setBoolean("decayOutsideZones",decayOutsideZones);n.setBoolean("advancedZoneSettings",advancedZoneSettings);n.setBoolean("mobsAttackSettlement",mobsAttackSettlement);n.setBoolean("requireMobZone",requireMobZone);n.setBoolean("raidsWithoutRuin",raidsWithoutRuin);n.setBoolean("warsWithoutRuin",warsWithoutRuin);n.setString("blacklist",String.join(",",blacklist));featureSnapshot(n);return n;}
    public static void apply(NBTTagCompound n){String[] newBlacklist=n.hasKey("blacklist",8)?parseBlacklist(n.getString("blacklist")):blacklist;radius=integer(n,"radius",radius,4,128);requiredFlags=integer(n,"requiredFlags",requiredFlags,1,64);requiredPlayers=integer(n,"requiredPlayers",requiredPlayers,1,64);spawnMinDistance=integer(n,"spawnMinDistance",spawnMinDistance,0,256);spawnMaxDistance=Math.max(spawnMinDistance+1,integer(n,"spawnMaxDistance",spawnMaxDistance,1,512));firstSettlementDistance=integer(n,"firstSettlementDistance",firstSettlementDistance,0,1000000);decaySeconds=integer(n,"decaySeconds",decaySeconds,10,86400);
        defaultAllowed=bool(n,"defaultAllowed",defaultAllowed);protectClaims=bool(n,"protectClaims",protectClaims);preventBuildOutsideZones=bool(n,"preventBuildOutsideZones",preventBuildOutsideZones);decayOutsideZones=bool(n,"decayOutsideZones",decayOutsideZones);advancedZoneSettings=bool(n,"advancedZoneSettings",advancedZoneSettings);mobsAttackSettlement=bool(n,"mobsAttackSettlement",mobsAttackSettlement);requireMobZone=bool(n,"requireMobZone",requireMobZone);raidsWithoutRuin=bool(n,"raidsWithoutRuin",raidsWithoutRuin);warsWithoutRuin=bool(n,"warsWithoutRuin",warsWithoutRuin);blacklist=newBlacklist;applyFeatures(n);save();}
    private static void featureSnapshot(NBTTagCompound n){n.setBoolean("warGhostProtection",warGhostProtection);n.setBoolean("mobDestruction",mobDestruction);n.setBoolean("mobPlacement",mobPlacement);n.setBoolean("autoRepair",autoRepair);n.setBoolean("enableNpcs",enableNpcs);n.setInteger("maxNpcs",maxNpcs);n.setInteger("maxBlueprintVolume",maxBlueprintVolume);n.setInteger("raidWaves",raidWaves);n.setInteger("raidMobsPerWave",raidMobsPerWave);n.setInteger("raidRewardEmeralds",raidRewardEmeralds);}
    private static void applyFeatures(NBTTagCompound n){warGhostProtection=bool(n,"warGhostProtection",warGhostProtection);mobDestruction=bool(n,"mobDestruction",mobDestruction);mobPlacement=bool(n,"mobPlacement",mobPlacement);autoRepair=bool(n,"autoRepair",autoRepair);enableNpcs=bool(n,"enableNpcs",enableNpcs);maxNpcs=integer(n,"maxNpcs",maxNpcs,0,64);maxBlueprintVolume=integer(n,"maxBlueprintVolume",maxBlueprintVolume,1,262144);raidWaves=integer(n,"raidWaves",raidWaves,1,20);raidMobsPerWave=integer(n,"raidMobsPerWave",raidMobsPerWave,1,64);raidRewardEmeralds=integer(n,"raidRewardEmeralds",raidRewardEmeralds,0,64);}
    private static void saveFeatures(){config.get("war","warGhostProtection",warGhostProtection).set(warGhostProtection);config.get("defense","mobDestruction",mobDestruction).set(mobDestruction);config.get("defense","mobPlacement",mobPlacement).set(mobPlacement);config.get("blueprints","autoRepair",autoRepair).set(autoRepair);config.get("npc","enableNpcs",enableNpcs).set(enableNpcs);config.get("npc","maxNpcs",maxNpcs).set(maxNpcs);config.get("blueprints","maxBlueprintVolume",maxBlueprintVolume).set(maxBlueprintVolume);config.get("defense","raidWaves",raidWaves).set(raidWaves);config.get("defense","raidMobsPerWave",raidMobsPerWave).set(raidMobsPerWave);config.get("defense","raidRewardEmeralds",raidRewardEmeralds).set(raidRewardEmeralds);}
    public static String[] parseBlacklist(String text){if(text.length()>2048)throw new IllegalArgumentException("Blacklist is too long");java.util.List<String> ids=new java.util.ArrayList<>();for(String part:text.split(",")){String id=part.trim();if(!id.isEmpty()){if(!id.matches("[a-z0-9_.-]+:[a-z0-9_/.-]+"))throw new IllegalArgumentException("Blacklist entries need namespace:block registry names");ids.add(id);}}return ids.toArray(new String[0]);}
    private static int integer(NBTTagCompound n,String k,int d,int min,int max){return n.hasKey(k,3)?Math.max(min,Math.min(max,n.getInteger(k))):d;}
    private static boolean bool(NBTTagCompound n,String k,boolean d){return n.hasKey(k,1)?n.getBoolean(k):d;}
    public static void save(){if(config==null)return;config.get("settlements","radius",radius).set(radius);config.get("settlements","requiredFlags",requiredFlags).set(requiredFlags);config.get("settlements","requiredPlayers",requiredPlayers).set(requiredPlayers);config.get("settlements","protectClaims",protectClaims).set(protectClaims);config.get("zones","defaultAllowed",defaultAllowed).set(defaultAllowed);config.get("zones","preventBuildOutsideZones",preventBuildOutsideZones).set(preventBuildOutsideZones);config.get("zones","decayOutsideZones",decayOutsideZones).set(decayOutsideZones);config.get("zones","advancedZoneSettings",advancedZoneSettings).set(advancedZoneSettings);config.get("zones","firstSettlementDistance",firstSettlementDistance).set(firstSettlementDistance);config.get("zones","decaySeconds",decaySeconds).set(decaySeconds);config.get("defense","mobsAttackSettlement",mobsAttackSettlement).set(mobsAttackSettlement);config.get("defense","requireMobZone",requireMobZone).set(requireMobZone);config.get("defense","spawnMinDistance",spawnMinDistance).set(spawnMinDistance);config.get("defense","spawnMaxDistance",spawnMaxDistance).set(spawnMaxDistance);config.get("defense","raidsWithoutRuin",raidsWithoutRuin).set(raidsWithoutRuin);config.get("war","warsWithoutRuin",warsWithoutRuin).set(warsWithoutRuin);config.get("zones","blacklist",blacklist).set(blacklist);saveFeatures();config.save();}
}




